import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1790923704000}'),d={name:"guide/architecture.md"};function r(s,e,i,c,l,p){return t(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>NeoFlux splits a UI application into two independently threaded layers that communicate through a single lock-free queue. The application layer owns all business logic and layout; the render layer owns the GPU/GL context and turns recorded commands into pixels.</p><h2 id="two-layer-split" tabindex="-1">Two-layer split <a class="header-anchor" href="#two-layer-split" aria-label="Permalink to &quot;Two-layer split&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+----------------------- Application thread (Application::Run) ----------------------+</span></span>
<span class="line"><span>|                                                                                   |</span></span>
<span class="line"><span>|  EventLoop (--target_fps)                                                          |</span></span>
<span class="line"><span>|    |  OnFrame()                                                                   |</span></span>
<span class="line"><span>|    |   1. PollEvents() + ShouldClose()                                            |</span></span>
<span class="line"><span>|    |   2. BuildDirtyWidgets()    rebuild dirty StatefulWidget subtrees            |</span></span>
<span class="line"><span>|    |   3. LayoutWidgetTree()     Taitank flexbox over the widget tree             |</span></span>
<span class="line"><span>|    |   4. PaintAndSubmit()       record kBeginFrame .. draw* .. kEndFrame         |</span></span>
<span class="line"><span>|    |                          |                                                   |</span></span>
<span class="line"><span>|    |                          |  RenderLayer::Submit(commands, n)                 |</span></span>
<span class="line"><span>|    |                          v                                                   |</span></span>
<span class="line"><span>|    |                SpscRingQueue&lt;RenderCommand&gt;   &lt;-- 1 producer, 1 consumer     |</span></span>
<span class="line"><span>+----|--------------------------|----------------------------------------------------+</span></span>
<span class="line"><span>     |  frame_cv_.notify_one   |</span></span>
<span class="line"><span>+----|--------------------------v----------------------------------------------------+</span></span>
<span class="line"><span>|    |              Render thread (RenderLayer::RenderLoop)                          |</span></span>
<span class="line"><span>|    |                 waits on frame_cv_, drains queue, honors Begin/End bounds     |</span></span>
<span class="line"><span>|    |                            |                                                 |</span></span>
<span class="line"><span>|    |                            v                                                 |</span></span>
<span class="line"><span>|    |                     TgfxRenderer  (tgfx, or built-in GL fallback)            |</span></span>
<span class="line"><span>|    |                            |                                                 |</span></span>
<span class="line"><span>|    |      desktop: GlfwBridge (GLFW window + WGL context) -&gt; SwapBuffers()        |</span></span>
<span class="line"><span>|    |      mobile:  platform surface (ANativeWindow / CAMetalLayer)                 |</span></span>
<span class="line"><span>+----+-----------------------------------------------------------------------------+</span></span></code></pre></div><h2 id="application-layer-ui-thread" tabindex="-1">Application layer (UI thread) <a class="header-anchor" href="#application-layer-ui-thread" aria-label="Permalink to &quot;Application layer (UI thread)&quot;">​</a></h2><p>Runs on the thread that calls <code>Application::Run()</code>. It is the only thread that may touch widget objects.</p><ul><li><strong>Widget tree</strong> — a <code>shared_ptr</code> tree of <code>Widget</code> nodes. Stateful widgets rebuild their subtree; leaf widgets (<code>Text</code>, <code>Button</code>) report intrinsic sizes.</li><li><strong>Taitank layout</strong> — every <code>Widget</code> owns an opaque <code>taitank::TaitankNode</code>. <code>PerformLayout(w, h)</code> runs <code>taitank::DoLayout</code> on the root and copies the computed rectangles back into the widgets.</li><li><strong>Event loop</strong> — a condition-variable-driven loop in <code>EventLoop</code>. It sleeps when idle and is woken by <code>WakeUp()</code> (input, <code>MarkFrameDirty()</code>, timers). <code>--target_fps</code> caps the maximum frame rate.</li><li><strong>Command recording</strong> — during <code>PaintAndSubmit()</code> the application appends a <code>kBeginFrame</code> marker, the widget paint calls (draw / clip / text commands), and a <code>kEndFrame</code> marker into a <code>RenderContext</code>.</li></ul><p>A frame is only produced when something is actually dirty — <code>OnFrame()</code> early- outs if neither <code>frame_dirty_</code> nor a widget rebuild occurred, which keeps idle CPU near zero.</p><h2 id="render-layer-render-thread" tabindex="-1">Render layer (render thread) <a class="header-anchor" href="#render-layer-render-thread" aria-label="Permalink to &quot;Render layer (render thread)&quot;">​</a></h2><p><code>RenderLayer::Start()</code> spawns a dedicated <code>std::thread</code> running <code>RenderLoop()</code>. This thread exclusively owns the GL context.</p><ul><li><strong>GL context ownership</strong> — on desktop the context is created by the <code>GlfwBridge</code>. It is briefly made current on the main thread so the OpenGL loader (<code>glfwGetProcAddress</code> / WGL) can resolve function pointers, then released and re-acquired on the render thread for all actual drawing.</li><li><strong>Frame state machine</strong> — commands are only executed between <code>kBeginFrame</code> and <code>kEndFrame</code>. This prevents the render thread from presenting a partial frame while the application is still submitting commands.</li><li><strong>Backend</strong> — <code>TgfxRenderer</code> wraps <code>tgfx</code>. When <code>NEOFLUX_USE_TGFX</code> is off, the same class falls back to a built-in OpenGL renderer (shader + VBO + FreeType glyph atlas). The <code>--render_backend</code> flag defaults to <code>gl</code> (the only backend available in this build); <code>vulkan</code>, <code>cpu</code>, and unknown values are a hard startup error rather than a silent GL fallback.</li></ul><h2 id="how-commands-cross-threads" tabindex="-1">How commands cross threads <a class="header-anchor" href="#how-commands-cross-threads" aria-label="Permalink to &quot;How commands cross threads&quot;">​</a></h2><p>The two layers never call each other&#39;s rendering code across a frame. Instead:</p><ol><li>The <strong>application thread</strong> is the sole producer: <code>RenderLayer::Submit()</code> calls <code>command_queue_.TryPush(cmd)</code> for every recorded command. If the queue is full the overflowing commands are dropped (rate-limited warning).</li><li><code>Submit()</code> then sets <code>frame_ready_ = true</code> and <code>frame_cv_.notify_one()</code> to wake the render thread.</li><li>The <strong>render thread</strong> is the sole consumer: it waits on <code>frame_cv_</code> (16 ms max), then <code>TryPop()</code>s every available command and dispatches it to <code>TgfxRenderer</code>. At <code>kEndFrame</code> it calls <code>EndFrame()</code> and, on desktop, <code>GlfwBridge::SwapBuffers()</code>.</li></ol><h3 id="spscringqueue-details" tabindex="-1">SpscRingQueue details <a class="header-anchor" href="#spscringqueue-details" aria-label="Permalink to &quot;SpscRingQueue details&quot;">​</a></h3><p>Defined in <code>include/neoflux/core/ring_queue.h</code>:</p><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td>Kind</td><td>Bounded, <strong>single-producer / single-consumer</strong>, lock-free</td></tr><tr><td>Capacity</td><td>Set by <code>--render_queue_capacity</code> (default <code>2048</code>), rounded up to the next power of two</td></tr><tr><td>Usable slots</td><td><code>capacity - 1</code> (one slot reserved to distinguish full from empty)</td></tr><tr><td>Indices</td><td><code>head_</code> (producer) and <code>tail_</code> (consumer) are <code>alignas(64)</code> to avoid false sharing on cache-line boundaries</td></tr><tr><td>Wrap-around</td><td>Power-of-two size lets index wrapping use <code>&amp; mask_</code> instead of <code>%</code></td></tr><tr><td>API</td><td><code>TryPush()</code> (producer), <code>TryPop()</code> (consumer), plus <code>Empty()</code> / <code>Full()</code> / <code>Size()</code> snapshots</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Only one producer and one consumer</p><p>The queue is intentionally SPSC-safe, not MPMC. Never push to it from the render thread or pop from the application thread. The <code>frame_cv_</code> condition variable is the only mutex-protected hand-shake; the queue itself is wait-free.</p></div><h2 id="input-flow" tabindex="-1">Input flow <a class="header-anchor" href="#input-flow" aria-label="Permalink to &quot;Input flow&quot;">​</a></h2><p>Pointer and scroll events originate on the window thread via the <code>GlfwBridge</code> and are delivered to <code>Application</code>, which:</p><ol><li>Scales cursor coordinates from the real (DPI-scaled) window size to the logical layout size.</li><li>Runs a recursive <code>HitTest()</code> (children tested top-most first), with a hover hit-cache that is invalidated on every layout change.</li><li>Routes press/release to the widget that consumed the press, move events to the hovered (or pressed) widget, and lets scroll events <strong>bubble up</strong> ancestors until one consumes them.</li></ol><p><code>pressed_widget_</code> is held as a <code>weak_ptr</code> so a widget-tree rebuild between press and release cannot leave a dangling pointer. See <a href="./input">Input &amp; Events</a> for the full event contract.</p><h2 id="platform-matrix" tabindex="-1">Platform matrix <a class="header-anchor" href="#platform-matrix" aria-label="Permalink to &quot;Platform matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Windowing</th><th>GL/GL context</th><th>Render target</th></tr></thead><tbody><tr><td>Windows / Linux / macOS</td><td><code>GlfwBridge</code> (GLFW)</td><td>WGL / GLX / CGL via GLFW</td><td>window framebuffer</td></tr><tr><td>Android / iOS</td><td>OS-provided surface</td><td>n/a</td><td><code>ANativeWindow</code> / <code>CAMetalLayer</code></td></tr></tbody></table><p>The preprocessor selects the bridge: <code>glfw_bridge.cpp</code> is built on desktop, <code>mobile_bridge.cpp</code> on Android/iOS (<code>NEOFLUX_PLATFORM_DESKTOP</code> vs <code>NEOFLUX_PLATFORM_MOBILE</code>).</p>`,25)])])}const m=a(d,[["render",r]]);export{u as __pageData,m as default};
